params.script:
const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4'));
const target = headings.find(h => h.textContent.trim() === 'Mais lidas');
if (!target) { return 'ERRO: widget Mais lidas nao encontrado'; }
const container = target.closest('.mostRead') || target.parentElement;
const links = Array.from(container.querySelectorAll('a')).filter(a => a.textContent.trim().length > 0);
return links.slice(0, 5).map((a, i) => (i + 1) + '. ' + a.textContent.trim()).join('\n');
